// == CAL :: DATE-RANGE-PATCH v1 (global) ==
(function(){
  if (window.__calDRPPatched) return; window.__calDRPPatched = true;

  function MODE(){ try{ return localStorage.getItem('CAL_MODE') || 'jalali'; }catch(e){ return 'jalali'; } }

  async function ensureLibs(){
    function addCss(h){ return new Promise(function(r,j){ try{
      if(document.querySelector("link[href^='"+h+"']")) return r();
      var l=document.createElement('link'); l.rel='stylesheet'; l.href=h;
      l.onload=r; l.onerror=j; document.head.appendChild(l);
    }catch(e){ j(e); } }); }
    function addJs(s){ return new Promise(function(r,j){ try{
      if(document.querySelector("script[src^='"+s+"']")) return r();
      var e=document.createElement('script'); e.src=s;
      e.onload=r; e.onerror=j; document.body.appendChild(e);
    }catch(e){ j(e); } }); }
    await addCss('https://cdn.jsdelivr.net/npm/persian-datepicker@1.2.0/dist/css/persian-datepicker.min.css');
    await addJs ('https://cdn.jsdelivr.net/npm/persian-date@1.1.0/dist/persian-date.min.js');
    await addJs ('https://cdn.jsdelivr.net/npm/persian-datepicker@1.2.0/dist/js/persian-datepicker.min.js');
    return !!(window.persianDate && window.jQuery && jQuery.fn.pDatepicker);
  }

  function bindPair(inpFa, inpFa2, inpEn, inpEn2){
    try{ jQuery(inpFa).pDatepicker('destroy'); jQuery(inpFa2).pDatepicker('destroy'); }catch(e){}
    jQuery(inpFa).pDatepicker({
      autoClose:true, initialValue:false, format:'YYYY/MM/DD',
      altField:inpEn, altFormat:'YYYY-MM-DD',
      onSelect:function(unix){ try{ var d=new persianDate(unix).toDate(); jQuery(inpFa2).pDatepicker('setMinDate', d.getTime()); }catch(e){} }
    });
    jQuery(inpFa2).pDatepicker({
      autoClose:true, initialValue:false, format:'YYYY/MM/DD',
      altField:inpEn2, altFormat:'YYYY-MM-DD',
      onSelect:function(unix){ try{ var d=new persianDate(unix).toDate(); jQuery(inpFa).pDatepicker('setMaxDate', d.getTime()); }catch(e){} }
    });
  }

  (function install(){
    if (!window.frappe || !frappe.ui) return;
    var Orig = frappe.ui.DateRangePicker;
    if (!Orig || frappe.__CAL_Orig_DRP) return;
    frappe.__CAL_Orig_DRP = Orig;

    frappe.ui.DateRangePicker = function(opts){
      this.opts = opts || {};
      this.from_date = this.opts.from_date || null;
      this.to_date   = this.opts.to_date   || null;

      var self = this;
      this.show = async function(){
        if (MODE() !== 'jalali' || !(await ensureLibs())) { try{ return new Orig(self.opts).show(); }catch(e){ return; } }
        var dlg = new frappe.ui.Dialog({
          title: 'انتخاب بازهٔ زمانی (شمسی)',
          fields: [
            {fieldtype:'Section Break'},
            {label:'از', fieldname:'from_fa', fieldtype:'Data'},
            {fieldtype:'Column Break'},
            {label:'تا', fieldname:'to_fa', fieldtype:'Data'},
            {fieldtype:'Section Break'},
            {fieldtype:'HTML', fieldname:'hint', options:'<div style="opacity:.7;font-size:12px">نمایش شمسی؛ ارسال به سرور: <code>YYYY-MM-DD</code> (میلادی)</div>'}
          ],
          primary_action_label: 'اعمال',
          primary_action: function(){
            var from_g = dlg._from_en.value || '';
            var to_g   = dlg._to_en.value   || '';
            try{
              if (typeof self.opts.set_value === 'function') self.opts.set_value(from_g, to_g);
              if (typeof self.opts.on_change === 'function') self.opts.on_change(from_g, to_g);
              if (typeof self.opts.callback === 'function') self.opts.callback(from_g, to_g);
              if (typeof self.opts.update_date_range === 'function') self.opts.update_date_range(from_g, to_g);
            }catch(e){}
            dlg.hide();
          }
        });
        dlg._from_en = document.createElement('input');
        dlg._to_en   = document.createElement('input');
        dlg._from_en.type='hidden'; dlg._to_en.type='hidden';
        dlg.body.appendChild(dlg._from_en); dlg.body.appendChild(dlg._to_en);

        var fromFa = dlg.get_field('from_fa').$input[0];
        var toFa   = dlg.get_field('to_fa').$input[0];
        try{ fromFa.classList.add('form-control'); toFa.classList.add('form-control'); }catch(e){}
        bindPair(fromFa, toFa, dlg._from_en, dlg._to_en);
        dlg.show();
      };

      this.hide = function(){};
      return this;
    };
  })();
})();



// == CAL :: CHART-PATCH v2 (fa month + latin digits) ==
(function(){
  if (window.__calChartPatched) return; window.__calChartPatched = true;
  const MODE = ()=>{ try{return localStorage.getItem("CAL_MODE")||"jalali"}catch(e){return "jalali"} };
  const enDigits = s => String(s).replace(/[۰-۹]/g, m => "0123456789"["۰۱۲۳۴۵۶۷۸۹".indexOf(m)]);
  async function ensureLibs(){
    function addCss(h){return new Promise((r,j)=>{try{if(document.querySelector(`link[href^="${h}"]`))return r();const l=document.createElement("link");l.rel="stylesheet";l.href=h;l.onload=r;l.onerror=j;document.head.appendChild(l);}catch(e){j(e)}});}
    function addJs(s){ return new Promise((r,j)=>{try{if(document.querySelector(`script[src^="${s}"]`))return r();const e=document.createElement("script");e.src=s;e.onload=r;e.onerror=j;document.body.appendChild(e);}catch(e){j(e)}});}
    await addCss("https://cdn.jsdelivr.net/npm/persian-datepicker@1.2.0/dist/css/persian-datepicker.min.css");
    await addJs ("https://cdn.jsdelivr.net/npm/persian-date@1.1.0/dist/persian-date.min.js");
    await addJs ("https://cdn.jsdelivr.net/npm/persian-datepicker@1.2.0/dist/js/persian-datepicker.min.js");
    try{ if(window.persianDate?.toLocale) window.persianDate.toLocale("fa"); }catch(e){}
    return !!window.persianDate;
  }
  function toDate(label){
    if (/^\d{4}[-/]\d{2}[-/]\d{2}/.test(label)) return new Date(label.replace(/-/g,"/")+" 00:00:00");
    if (/^[A-Za-z]{3}\s+\d{4}$/.test(label)) return new Date("01 "+label+" 00:00:00");
    if (/^[A-Za-z]{3}\s+\d{1,2},\s*\d{4}$/.test(label)) return new Date(label);
    if (/^\d{10,13}$/.test(String(label))){const n=+label;return new Date(n<1e12?n*1000:n);}
    return null;
  }
  function toJalaliLabel(label){
    try{
      const d=toDate(label); if(!d||isNaN(d)||!window.persianDate) return label;
      const s=new window.persianDate(d).format("MMM YYYY"); // ماه فارسی
      return enDigits(s); // ارقام لاتین
    }catch(e){ return label; }
  }
  function patchOpts(options){
    if (MODE()!=="jalali" || !options) return options;
    try{ const o=JSON.parse(JSON.stringify(options));
      if (o.data?.labels) o.data.labels = o.data.labels.map(toJalaliLabel);
      return o;
    }catch(e){ return options; }
  }
  const Orig=(window.frappe&&window.frappe.Chart)?window.frappe.Chart:null;
  async function install(){
    if(!Orig) return;
    await ensureLibs();
    const New=function(target,opts){ return new Orig(target, patchOpts(opts)); };
    try{ New.prototype=Orig.prototype; }catch(e){}
    window.frappe.Chart=New;
  }
  install(); setTimeout(install,300); setTimeout(install,1200);
})();



// == CAL :: CHART-PATCH (global, once) ==
(function(){
  if (window.__calChartPatched) return; window.__calChartPatched = true;

  const MODE = ()=>{ try{return localStorage.getItem("CAL_MODE")||"jalali"}catch(e){return "jalali"} };

  async function ensureLibs(){
    function addCss(h){return new Promise((r,j)=>{try{if(document.querySelector(`link[href^="${h}"]`))return r();const l=document.createElement("link");l.rel="stylesheet";l.href=h;l.onload=r;l.onerror=j;document.head.appendChild(l);}catch(e){j(e)}});}
    function addJs (s){return new Promise((r,j)=>{try{if(document.querySelector(`script[src^="${s}"]`))return r();const e=document.createElement("script");e.src=s;e.onload=r;e.onerror=j;document.body.appendChild(e);}catch(e){j(e)}});}
    await addCss("https://cdn.jsdelivr.net/npm/persian-datepicker@1.2.0/dist/css/persian-datepicker.min.css");
    await addJs ("https://cdn.jsdelivr.net/npm/persian-date@1.1.0/dist/persian-date.min.js");
    await addJs ("https://cdn.jsdelivr.net/npm/persian-datepicker@1.2.0/dist/js/persian-datepicker.min.js");
    return !!(window.persianDate);
  }

  function toDate(label){
    // ISO (YYYY-MM-DD) or YYYY/MM/DD
    if (/^\d{4}[-/]\d{2}[-/]\d{2}/.test(label)) {
      const s = label.replace(/-/g,"/"); return new Date(s+" 00:00:00");
    }
    // Mon YYYY  (e.g., "Mar 2025")
    if (/^[A-Za-z]{3}\s+\d{4}$/.test(label)) {
      return new Date("01 "+label+" 00:00:00");
    }
    // Mon DD, YYYY
    if (/^[A-Za-z]{3}\s+\d{1,2},\s*\d{4}$/.test(label)) {
      return new Date(label);
    }
    // numeric timestamp
    if (/^\d{10,13}$/.test(String(label))) {
      const n = Number(label); return new Date(n < 1e12 ? n*1000 : n);
    }
    return null;
  }

  function toJalaliLabel(label){
    try{
      const d = toDate(label);
      if (!d || isNaN(d) || !window.persianDate) return label;
      return new window.persianDate(d).format("MMM YYYY"); // محور ماه/سال
    }catch(e){ return label; }
  }

  function patchOpts(options){
    if (MODE()!=="jalali" || !options) return options;
    try{
      const o = JSON.parse(JSON.stringify(options));
      if (o.data && Array.isArray(o.data.labels)) {
        o.data.labels = o.data.labels.map(toJalaliLabel);
      }
      return o;
    }catch(e){ return options; }
  }

  const Orig = (window.frappe && window.frappe.Chart) ? window.frappe.Chart : null;

  async function install(){
    if (!Orig) return; // if charts lib not present on this view, harmless
    await ensureLibs();
    const NewCtor = function(target, opts){
      return new Orig(target, patchOpts(opts));
    };
    // copy prototype to keep methods working (update/addData/...)
    try{ NewCtor.prototype = Orig.prototype; }catch(e){}
    window.frappe.Chart = NewCtor;
  }

  // install now (and again soon for late loads)
  install(); setTimeout(install, 300); setTimeout(install, 1200);
})();


