// == CAL :: CHART-PATCH (global, once) ==
(function(){
  if (window.__calChartPatched) return; window.__calChartPatched = true;

  const MODE = ()=>{ try{return localStorage.getItem("CAL_MODE")||"jalali"}catch(e){return "jalali"} };

  async function ensureLibs(){
    function addCss(h){return new Promise((r,j)=>{try{if(document.querySelector(`link[href^="${h}"]`))return r();const l=document.createElement("link");l.rel="stylesheet";l.href=h;l.onload=r;l.onerror=j;document.head.appendChild(l);}catch(e){j(e)}});}
    function addJs (s){return new Promise((r,j)=>{try{if(document.querySelector(`script[src^="${s}"]`))return r();const e=document.createElement("script");e.src=s;e.onload=r;e.onerror=j;document.body.appendChild(e);}catch(e){j(e)}});}
    await addCss("https://cdn.jsdelivr.net/npm/persian-datepicker@1.2.0/dist/css/persian-datepicker.min.css");
    await addJs ("https://cdn.jsdelivr.net/npm/persian-date@1.1.0/dist/persian-date.min.js");
    await addJs ("https://cdn.jsdelivr.net/npm/persian-datepicker@1.2.0/dist/js/persian-datepicker.min.js");
    return !!(window.persianDate);
  }

  function toDate(label){
    // ISO (YYYY-MM-DD) or YYYY/MM/DD
    if (/^\d{4}[-/]\d{2}[-/]\d{2}/.test(label)) {
      const s = label.replace(/-/g,"/"); return new Date(s+" 00:00:00");
    }
    // Mon YYYY  (e.g., "Mar 2025")
    if (/^[A-Za-z]{3}\s+\d{4}$/.test(label)) {
      return new Date("01 "+label+" 00:00:00");
    }
    // Mon DD, YYYY
    if (/^[A-Za-z]{3}\s+\d{1,2},\s*\d{4}$/.test(label)) {
      return new Date(label);
    }
    // numeric timestamp
    if (/^\d{10,13}$/.test(String(label))) {
      const n = Number(label); return new Date(n < 1e12 ? n*1000 : n);
    }
    return null;
  }

  function toJalaliLabel(label){
    try{
      const d = toDate(label);
      if (!d || isNaN(d) || !window.persianDate) return label;
      return new window.persianDate(d).format("MMM YYYY"); // محور ماه/سال
    }catch(e){ return label; }
  }

  function patchOpts(options){
    if (MODE()!=="jalali" || !options) return options;
    try{
      const o = JSON.parse(JSON.stringify(options));
      if (o.data && Array.isArray(o.data.labels)) {
        o.data.labels = o.data.labels.map(toJalaliLabel);
      }
      return o;
    }catch(e){ return options; }
  }

  const Orig = (window.frappe && window.frappe.Chart) ? window.frappe.Chart : null;

  async function install(){
    if (!Orig) return; // if charts lib not present on this view, harmless
    await ensureLibs();
    const NewCtor = function(target, opts){
      return new Orig(target, patchOpts(opts));
    };
    // copy prototype to keep methods working (update/addData/...)
    try{ NewCtor.prototype = Orig.prototype; }catch(e){}
    window.frappe.Chart = NewCtor;
  }

  // install now (and again soon for late loads)
  install(); setTimeout(install, 300); setTimeout(install, 1200);
})();


