(() => {
  const MODE_KEY = 'CAL_MODE';
  const getMode  = () => localStorage.getItem(MODE_KEY) || 'jalali';
  const setMode  = (m) => localStorage.setItem(MODE_KEY, m);
  const FIELDS   = ['transaction_date','delivery_date'];
  const $        = window.jQuery;

  const FILES = {
    css:  '/files/persian-datepicker.min.css',
    pdate:'/files/persian-date.min.js',
    ppick:'/files/persian-datepicker.min.js'
  };
  const CDN = {
    css:  'https://cdn.jsdelivr.net/npm/persian-datepicker@1.2.0/dist/css/persian-datepicker.min.css',
    pdate:'https://cdn.jsdelivr.net/npm/persian-date@1.1.0/dist/persian-date.min.js',
    ppick:'https://cdn.jsdelivr.net/npm/persian-datepicker@1.2.0/dist/js/persian-datepicker.min.js'
  };

  const pad=(n)=>String(n).padStart(2,'0');
  const toLocalDate=(iso)=>{
    if(!iso) return null;
    if(/^\d{4}-\d{2}-\d{2}$/.test(iso)) return new Date(`${iso}T00:00:00`);
    return new Date(String(iso).replace(' ','T'));
  };
  const jLong=(iso)=>{
    try{
      const d=toLocalDate(iso);
      if(!d || isNaN(d) || !window.persianDate) return '';
      return new window.persianDate(d).format('dddd D MMMM YYYY  h:mm a'); // دوشنبه ۶ آبان ۱۴۰۴  ۸:۱۴ ق ظ
    }catch{ return ''; }
  };

  const loadCss=(href)=>new Promise((res,rej)=>{
    if(document.querySelector(`link[href^="${href.split('?')[0]}"]`)) return res();
    const l=document.createElement('link'); l.rel='stylesheet'; l.href=href; l.onload=res; l.onerror=rej; document.head.appendChild(l);
  });
  const loadJs=(src)=>new Promise((res,rej)=>{
    if(document.querySelector(`script[src^="${src.split('?')[0]}"]`)) return res();
    const s=document.createElement('script'); s.src=src; s.onload=res; s.onerror=rej; document.body.appendChild(s);
  });
  async function ensureLibs(){
    try{await loadCss(FILES.css);}catch{await loadCss(CDN.css);}
    try{await loadJs(FILES.pdate);}catch{await loadJs(CDN.pdate);}
    try{await loadJs(FILES.ppick);}catch{await loadJs(CDN.ppick);}
    if(!document.getElementById('cal-css-fix')){
      const st=document.createElement('style'); st.id='cal-css-fix';
      st.textContent='.pwt-datepicker,.pwt-datepicker-container{z-index:2147483647!important;transform:translateY(-8px)!important} input.cal-proxy{direction:rtl}';
      document.head.appendChild(st);
    }
    return !!(window.jQuery && window.persianDate && jQuery.fn.pDatepicker);
  }

  function makeProxy(real){
    if(!real || real.dataset.calProxied==='1') return;
    if(!real.id) real.id = `cal-real-${real.getAttribute('data-fieldname')||Math.random().toString(36).slice(2)}`;

    // kill default flatpickr on these two fields only (avoid double picker)
    try{ if(real._flatpickr){ real._flatpickr.destroy(); real._flatpickr=null; } }catch{}

    const proxy=document.createElement('input');
    proxy.type='text';
    proxy.className='form-control cal-proxy';
    proxy.dir='rtl';
    proxy.placeholder=real.placeholder||'';
    real.style.display='none';
    (real.closest('.control-input')||real.parentElement).insertBefore(proxy, real);

    try{$(proxy).pDatepicker('destroy');}catch{}
    $(proxy).pDatepicker({
      autoClose:true,
      initialValue:false,
      format:'dddd D MMMM YYYY  h:mm a', // نمایش جلالیِ بلند در خود فیلد
      altField:'#'+real.id,               // مقدار واقعی → فیلد اصلی
      altFormat:'YYYY-MM-DD',             // ذخیره‌ی میلادی ISO
      timePicker:{enabled:true,second:{enabled:false}}
    });

    proxy.value = jLong(real.value);      // مقدار اولیه
    real.addEventListener('change',()=>{ proxy.value = jLong(real.value); });
    real.dataset.calProxied='1';
  }

  function bindJalali(ctx){
    FIELDS.forEach(fn=> makeProxy((ctx||document).querySelector(`input[data-fieldname="${fn}"]`)));
    // چند شلیک همگام‌سازی برای اولین بار
    [0,120,300,600,1000,1600,2400].forEach(t=>setTimeout(()=>{
      FIELDS.forEach(fn=>{
        const el=(ctx||document).querySelector(`input[data-fieldname="${fn}"]`);
        const p=el?.previousElementSibling;
        if(el && p && p.classList.contains('cal-proxy')) p.value = jLong(el.value);
      });
    },t));
  }

  function unbindJalali(ctx){
    (ctx||document).querySelectorAll('input.cal-proxy').forEach(p=>{
      try{$(p).pDatepicker('destroy');}catch{}
      const real=p.nextElementSibling; if(real) real.style.display=''; p.remove();
    });
    FIELDS.forEach(fn=>{
      const r=(ctx||document).querySelector(`input[data-fieldname="${fn}"]`);
      if(r) delete r.dataset.calProxied;
    });
  }

  function ensureToggle(frm){
    if(!frm?.add_custom_button) return;
    if(frm.__calBtn){ frm.__calBtn.text(getMode()==='jalali'?'تقویم: شمسی':'تقویم: میلادی'); return; }
    frm.__calBtn = frm.add_custom_button(getMode()==='jalali'?'تقویم: شمسی':'تقویم: میلادی', async ()=>{
      const next=getMode()==='jalali'?'gregorian':'jalali'; setMode(next);
      if(next==='jalali'){
        const ok=await ensureLibs(); if(ok){ bindJalali(frm.$wrapper[0]); }
      }else{
        unbindJalali(frm.$wrapper[0]); frm.refresh_fields(FIELDS);
      }
      frm.__calBtn.text(getMode()==='jalali'?'تقویم: شمسی':'تقویم: میلادی');
    }, null, 'btn-default');
  }

  async function boot(frm){
    ensureToggle(frm);
    if(getMode()==='jalali'){
      const ok=await ensureLibs(); if(ok){ bindJalali(frm.$wrapper[0]); }
    }else{
      unbindJalali(frm.$wrapper[0]);
    }
  }

  frappe.ui.form.on('Sales Order', {
    refresh(frm){ boot(frm); },
    onload_post_render(frm){ if(getMode()==='jalali') ensureLibs().then(()=>bindJalali(frm.$wrapper[0])); }
  });
})();

