      const ok=await ensureLibs(); if(ok){ bindJalali(frm.$wrapper[0]); }
    }else{
      unbindJalali(frm.$wrapper[0]);
    }
  }

  frappe.ui.form.on('Sales Order', {
    refresh(frm){ boot(frm); },
    onload_post_render(frm){ if(getMode()==='jalali') ensureLibs().then(()=>bindJalali(frm.$wrapper[0])); }
  });
})();
